(function(){
'use strict';
const C=window.AC01Content,E=window.AC01Engine,KEY=E.SCHEMA,app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.fresh(),saving=true,blocked=false,raw='',notice='',step=0,lab=[0,0];
try{raw=localStorage.getItem(KEY)||'';if(raw){const loaded=E.hydrate(JSON.parse(raw));if(loaded)state=loaded;else blocked=true;}}catch{if(raw)blocked=true;else saving=false;}
function save(){if(!blocked){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{saving=false;}}document.getElementById('storage-note').textContent=saving?'Progress stays in this browser. No account needed.':'Browser saving is unavailable. Keep this tab open to finish.';}
function lesson(){return C.LESSONS[state.lessonIndex];}
function currentTask(){return state.view==='lesson'?(state.stage==='predict'?lesson().predict:state.stage==='check'?lesson().checks[state.questionIndex]:null):null;}
function button(action,label,cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function nav(){return `<nav class="lesson-nav" aria-label="Game theory lessons">${button('home','Start here','quiet')}${C.LESSONS.map((l,i)=>`<button class="lesson-link ${state.view==='lesson'&&state.lessonIndex===i?'active':''}" data-action="open" data-index="${i}" ${state.view==='lesson'&&state.lessonIndex===i?'aria-current="page"':''}><span class="lesson-number">${E.lessonDone(state,i)?'✓':i+1}</span>${esc(l.short)}</button>`).join('')}${button('summary','My summary','quiet',E.allDone(state)?'':'disabled')}</nav>`;}
function path(){return `<ol class="phase-path" aria-label="Current lesson phases">${[['predict','First thought'],['learn','Explore & learn'],['check','Fresh questions'],['review','Feedback']].map(([id,name])=>`<li class="${state.stage===id?'current':''}" ${state.stage===id?'aria-current="step"':''}>${name}</li>`).join('')}</ol>`;}
function payoffTable(game,selected=null){return `<div class="table-wrap"><table class="payoffs"><caption>${esc(game.name)} <span class="caption-note">Each cell: (A’s payoff, B’s payoff)</span></caption><thead><tr><th scope="col">A ↓ · B →</th>${game.cols.map(x=>`<th scope="col">B: ${esc(x)}</th>`).join('')}</tr></thead><tbody>${game.rows.map((x,r)=>`<tr><th scope="row">A: ${esc(x)}</th>${game.cols.map((_,c)=>`<td class="${selected&&selected[0]===r&&selected[1]===c?'selected':''}"><span class="payoff-a">${game.payoffs[r][c][0]}</span><span class="comma">, </span><span class="payoff-b">${game.payoffs[r][c][1]}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function orientation(){const started=Object.keys(state.records).length>0;return `<section class="hero"><p class="eyebrow">GAME THEORY · FOUR SMALL LESSONS</p><h1>Your choice.<br>Their choice.<br>A shared outcome.</h1><p class="lead">What changes when your result depends on someone else? Start with a small decision, explore a payoff table, then try the idea in a new situation.</p><div class="actions">${button('start',started?'Resume learning →':'Start the first lesson →','primary')}<span class="tiny">No game theory background needed.</span></div><div class="hero-art" aria-hidden="true"><div class="art-label">TWO CHOICES, ONE OUTCOME</div><div class="art-players"><span>A<br><small>Your choice</small></span><span>B<br><small>Their choice</small></span></div><div class="art-outcome">(3, 5)<small>Two separate payoffs</small></div></div></section><section class="orientation-grid"><article class="card"><p class="eyebrow">HOW IT WORKS</p><h2>Think. Explore. Try again.</h2><ol class="simple-list"><li>Make a first prediction. “I’m not sure” is welcome.</li><li>Read four short steps and explore the table.</li><li>Answer two fresh questions, then see feedback.</li></ol><p class="muted">You only need to compare small numbers. The example is guided; the new questions check whether you can use the idea.</p></article><article class="card"><p class="eyebrow">WHAT YOU’LL EXPLORE</p><h2>Four useful ways to think.</h2><ul class="topic-list">${C.LESSONS.map((l,i)=>`<li><span>${i+1}</span><div>${esc(l.title)}<small>${esc(l.goal)}</small></div></li>`).join('')}</ul></article></section><p><a href="projects/">Explore two projects and a case study →</a></p><p class="privacy-note">Your answers stay in this browser. You can download a summary after all four lessons. No name or sign-up is requested.</p>`;}
function taskHtml(t){const r=E.record(state,t.id),game=t.game&&C.GAMES[t.game],pre=state.stage==='predict';return `<section class="card task-card"><p class="eyebrow">${pre?'BEFORE THIS LESSON':`NEW SITUATION · QUESTION ${state.questionIndex+1} OF 2`}</p><h2>${pre?'What do you think?':'Try the idea yourself.'}</h2><p class="muted">${pre?'Make a first prediction before the explanation. Feedback comes after the fresh questions.':'Both answers will be saved before feedback is shown. You can revise your answer before moving on.'}</p>${game?`<p>${esc(game.story)}</p>${payoffTable(game)}`:''}<form id="answer-form"><fieldset><legend>${esc(t.prompt)}</legend>${t.multi?'<p class="tiny">Select all that apply. “I’m not sure” and “No equilibrium” are separate choices.</p>':''}<div class="answer-options">${t.options.concat({id:'unsure',label:'I’m not sure yet'}).map(o=>`<label class="answer-option"><input type="${t.multi?'checkbox':'radio'}" name="choice" value="${o.id}" ${r.draft.choices.includes(o.id)?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}</div></fieldset><label class="explanation-label" for="explanation">Explain your thinking <span class="tiny">(optional; saved for review)</span></label><textarea id="explanation" name="explanation" rows="3" maxlength="3000" placeholder="Which payoffs did you compare?">${esc(r.draft.explanation)}</textarea><label class="help-label"><input type="checkbox" name="otherHelp" ${r.draft.otherHelp?'checked':''}> I used other help on this question.</label><div class="actions"><button type="submit" class="btn primary">${r.submissions.length?'Save this answer':'Save my answer'}</button>${button('next',pre?'Explore the idea →':state.questionIndex===0?'Next question →':'See the feedback →','',r.status==='submitted'?'':'disabled')}</div><p id="answer-status" class="status" role="status">${esc(notice||(r.status==='submitted'?'Answer saved. Continue when you are ready.':''))}</p></form></section>`;}
function learnHtml(){const l=lesson(),g=C.GAMES[l.game];if(!state.lessons[state.lessonIndex].seenSteps.includes(step)){state.lessons[state.lessonIndex].seenSteps.push(step);E.log(state,'lesson_step_viewed',{lesson:l.id,step});}const dA=E.deviation(g,...lab,0),dB=E.deviation(g,...lab,1),ne=E.equilibria(g).some(x=>x[0]===lab[0]&&x[1]===lab[1]);return `<section class="learning-grid"><article class="card lesson-copy"><p class="eyebrow">STEP ${step+1} OF 4</p><div class="step-tabs" aria-label="Worked lesson steps">${l.steps.map((_,i)=>`<button data-action="step" data-index="${i}" class="step-dot ${step===i?'active':''}" aria-label="Read step ${i+1}" ${step===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><h2>${esc(l.steps[step].title)}</h2><p class="lesson-text">${esc(l.steps[step].text)}</p><div class="actions">${button('prev-step','← Previous','quiet',step===0?'disabled':'')}${button('next-step',step<3?'Next step →':'Try fresh questions →','primary',step===3&&state.lessons[state.lessonIndex].seenSteps.length<4?'disabled':'')}</div><p class="tiny">${state.lessons[state.lessonIndex].seenSteps.length} of 4 steps opened. Try each comparison yourself.</p></article><article class="card explorer"><p class="eyebrow">PAYOFF EXPLORER</p><h2>Change one choice.</h2><p class="muted">${esc(g.story)} Higher payoffs are preferred.</p><div class="choice-controls"><label>A chooses<select id="row-choice">${g.rows.map((x,i)=>`<option value="${i}" ${lab[0]===i?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>B chooses<select id="col-choice">${g.cols.map((x,i)=>`<option value="${i}" ${lab[1]===i?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div>${payoffTable(g,lab)}<div class="outcome" aria-live="polite"><span>Current outcome</span><span><span class="payoff-a">A: ${g.payoffs[lab[0]][lab[1]][0]}</span><span class="payoff-b">B: ${g.payoffs[lab[0]][lab[1]][1]}</span></span></div>${state.lessonIndex>0?`<div class="switch-grid"><div><h3>Only A switches</h3><p>B stays at ${esc(g.cols[lab[1]])}.</p><p>A’s payoff: ${dA.before} → ${dA.after}</p><span class="switch-result">${dA.gain>0?'A gains':dA.gain<0?'A loses points':'A ties'}</span>${button('switch-a','Try A’s switch','small')}</div><div><h3>Only B switches</h3><p>A stays at ${esc(g.rows[lab[0]])}.</p><p>B’s payoff: ${dB.before} → ${dB.after}</p><span class="switch-result">${dB.gain>0?'B gains':dB.gain<0?'B loses points':'B ties'}</span>${button('switch-b','Try B’s switch','small')}</div></div>`:''}${state.lessonIndex===3?`<p class="equilibrium-note">${ne?'Neither player can gain by switching alone. This is a pure-strategy Nash equilibrium.':'At least one player can gain by switching alone. This is not a Nash equilibrium.'}</p>`:''}<p class="tiny">These are fictional payoffs, not measured real-world results. Changing a control explores the table; it does not submit an answer.</p></article></section>`;}
function resultLabel(result){return result==='correct'?'Correct on this question':result==='unsure'?'Not sure yet':'Revisit this idea';}
function answerText(t,a){return a.choices.map(id=>id==='unsure'?'I’m not sure yet':t.options.find(o=>o.id===id)?.label||id).join('; ');}
function reviewHtml(){const l=lesson(),initial=E.last(state,l.predict.id);return `<section class="card review"><p class="eyebrow">LESSON ${state.lessonIndex+1} · FEEDBACK</p><h2>What does your work show?</h2><div class="first-thought"><h3>Your first prediction</h3><p>${esc(answerText(l.predict,initial.answer))}</p><p class="tiny">${resultLabel(initial.result)}. This answer came before this lesson${initial.support.lessonSeen?' in this attempt; an earlier lesson visit was recorded':''}.</p><p>${esc(l.predict.explanation)}</p></div><h3>Fresh questions after instruction</h3>${l.checks.map((t,i)=>{const r=state.records[t.id],s=E.last(state,t.id);return `<article class="feedback-item"><span class="feedback-label ${s.result==='correct'?'correct':'revisit'}">${resultLabel(s.result)}</span><h4>${i+1}. ${esc(t.prompt)}</h4><p class="answer-line">Your answer: ${esc(answerText(t,s.answer))}</p><p>${esc(t.explanation)}</p>${s.answer.explanation?`<p class="written-answer">Your explanation: ${esc(s.answer.explanation)}</p>`:''}<p class="tiny">${s.support.otherHelp?'Other help was reported. ':''}${s.support.feedbackSeen?'This submission followed earlier feedback. ':''}${r.submissions.length>1?`${r.submissions.length} saved attempts; earlier answers remain in your history.`:'One saved attempt.'}</p>${button('revise','Revise this question','quiet small',`data-index="${i}"`)}</article>`;}).join('')}<div class="next-step-note"><h3>A useful next step</h3><p>${esc(l.checks.every(t=>E.last(state,t.id).result==='correct')?'Try a different payoff table and explain each comparison without the worked example.':l.next)}</p></div><p class="tiny">This is feedback on these questions, not a course grade. Written explanations are saved for human review.</p><div class="actions">${button('relearn','Reopen the lesson','quiet')}${button('continue',state.lessonIndex<3?'Continue to the next lesson →':E.allDone(state)?'See my summary →':'Visit an unfinished lesson →','primary')}</div></section>`;}
function summaryHtml(){return `<section class="summary-heading"><p class="eyebrow">YOUR FOUR-LESSON SUMMARY</p><h1>Choices, comparisons,<br>and next steps.</h1><p class="lead">Your first predictions and your new questions are kept separate. Correct answers here are evidence about these activities, not a complete measure of game theory understanding.</p></section><div class="card"><div class="table-wrap"><table class="summary-table"><thead><tr><th scope="col">Concept</th><th scope="col">First prediction</th><th scope="col">Fresh questions</th></tr></thead><tbody>${C.LESSONS.map((l,i)=>`<tr><th scope="row">${esc(l.title)}</th><td>${resultLabel(E.last(state,l.predict.id).result)}</td><td>${l.checks.map(t=>resultLabel(E.last(state,t.id).result)).join('<br>')}${button('open','View feedback','quiet small',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Fresh questions were answered after instruction. The saved history distinguishes first attempts, revisions, earlier feedback, and self-reported help. No effort or AI-use judgment is inferred.</p><div class="actions">${button('export-json','Download answer history','primary')}${button('export-md','Download readable summary')}${button('print','Print summary','quiet')}</div></div><section class="card next-steps"><h2>Where to go next</h2><p><a href="projects/">Explore two projects and a case study →</a></p><ul>${C.LESSONS.map(l=>`<li><span>${esc(l.short)}:</span> ${esc(l.next)}</li>`).join('')}</ul><p class="muted">Later lessons can introduce repeated games, mixed strategies, and sequential decisions. Those are not assessed in this version.</p><details><summary>Learning references</summary><p>All activities, numbers, and explanations here were newly written for this course. For a fuller course, see <a href="https://oyc.yale.edu/economics/econ-159/lecture-1" target="_blank" rel="noopener">Yale: introduction, dominance, and the prisoner’s dilemma</a> and <a href="https://oyc.yale.edu/economics/econ-159/lecture-5" target="_blank" rel="noopener">Yale: Nash equilibrium</a>.</p></details></section><section class="reset-section">${button('reset','Start a new session','quiet')}<p class="tiny">Download your history first if you want to keep it. A new session replaces this browser’s Game Theory record.</p></section><dialog id="reset-dialog"><h2>Start a new Game Theory session?</h2><p>Your current Game Theory answers will be replaced in this browser. Download your history first if you want to keep it.</p><div class="actions">${button('cancel-reset','Keep my answers')}${button('confirm-reset','Start new session','primary')}</div></dialog>`;}
function render(focus=false){
 if(blocked){app.innerHTML=`<section class="card recovery"><h1>Your saved session needs attention.</h1><p>It could not be read and has been kept unchanged. Download a copy before replacing it.</p><div class="actions">${button('raw','Download saved record','primary')}${button('reset-blocked','Replace with a new session')}</div></section><dialog id="reset-dialog"><h2>Replace the unreadable Game Theory record?</h2><p>Download the saved record first if you want to keep it.</p><div class="actions">${button('cancel-reset','Keep it')}${button('confirm-reset','Replace record','primary')}</div></dialog>`;return;}
 app.innerHTML=nav()+(state.view==='orientation'?orientation():state.view==='summary'?summaryHtml():`<section class="lesson-heading"><p class="eyebrow">LESSON ${state.lessonIndex+1} OF 4</p><h1>${esc(lesson().title)}</h1><p class="muted">${esc(lesson().goal)}</p>${path()}</section>`+(state.stage==='learn'?learnHtml():state.stage==='review'?reviewHtml():taskHtml(currentTask())));
 if(state.view==='summary'&&window.QuidenceReportStore){const saved=window.QuidenceReportStore.save('ac01',E.exportRecord(state),state.createdAt);window.QuidenceReportStore.appendNotice(app,saved);}
 const form=document.getElementById('answer-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();const t=currentTask();if(E.submit(state,t.id,state.stage)){notice='Answer saved. Continue when you are ready.';save();render();document.querySelector('[data-action="next"]').focus();}else{notice='Choose an answer or “I’m not sure yet,” then save it.';document.getElementById('answer-status').textContent=notice;}});
 save();if(focus){const heading=app.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus();}window.scrollTo({top:0,behavior:'instant'});}
}
function openLesson(index){state.lessonIndex=index;state.view='lesson';const l=lesson(),r=state.records[l.predict.id];step=0;lab=[...l.start];notice='';if(!r||r.status!=='submitted')state.stage='predict';else if(E.lessonDone(state,index))state.stage='review';else if(state.lessons[index].seenSteps.length===4){state.stage='check';state.questionIndex=l.checks.findIndex(t=>state.records[t.id]?.status!=='submitted');if(state.questionIndex<0)showReview();}else state.stage='learn';E.log(state,'lesson_opened',{lesson:l.id});render(true);}
function showReview(){state.stage='review';state.lessons[state.lessonIndex].reviewed=true;[lesson().predict,...lesson().checks].forEach(t=>E.record(state,t.id).feedbackSeen=true);E.log(state,'feedback_viewed',{lesson:lesson().id});}
function updateFromForm(event){const t=currentTask();if(!t)return;const form=document.getElementById('answer-form'),r=E.record(state,t.id);let choices=Array.from(form.querySelectorAll('[name="choice"]:checked')).map(x=>x.value);if(t.multi&&event.target.name==='choice'&&event.target.checked){if(['unsure','none'].includes(event.target.value))choices=[event.target.value];else choices=choices.filter(x=>!['unsure','none'].includes(x));form.querySelectorAll('[name="choice"]').forEach(x=>{x.checked=choices.includes(x.value);});}E.update(state,t.id,{choices,explanation:form.querySelector('[name="explanation"]').value,otherHelp:form.querySelector('[name="otherHelp"]').checked});notice=r.submissions.length?'Edited. Save again before continuing.':'';document.getElementById('answer-status').textContent=notice;document.querySelector('[data-action="next"]').disabled=true;save();}
app.addEventListener('input',event=>{if(event.target.closest('#answer-form'))updateFromForm(event);});
app.addEventListener('change',event=>{if(event.target.id==='row-choice'||event.target.id==='col-choice'){lab[event.target.id==='row-choice'?0:1]=Number(event.target.value);E.log(state,'table_explored',{lesson:lesson().id,row:lab[0],col:lab[1]});render();document.getElementById(event.target.id).focus();}});
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function markdown(){let s='# Game Theory Foundations\n\n'+`Session started: ${state.createdAt}\n\n`+'Initial predictions and checks after instruction are separate observations. This is not a course grade or a validated mastery score. Optional explanations need human review.\n\n';for(const l of C.LESSONS){s+=`## ${l.title}\n\n`;for(const t of [l.predict,...l.checks]){s+=`### ${t===l.predict?'Initial prediction':'Fresh question'}: ${t.prompt}\n\n`;state.records[t.id].submissions.forEach((r,i)=>{s+=`Attempt ${i+1}: ${answerText(t,r.answer)}\n\nResult: ${resultLabel(r.result)}\n\nSupport: lesson seen=${r.support.lessonSeen}; earlier feedback=${r.support.feedbackSeen}; other help reported=${r.support.otherHelp}\n\n`;if(r.answer.explanation)s+=`Explanation (not automatically scored):\n\n${r.answer.explanation.split('\n').map(line=>'> '+line).join('\n')}\n\n`;});s+=`${t.explanation}\n\n`;}s+=`Next step: ${l.next}\n\n`;}return s;}
app.addEventListener('click',event=>{
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,i=Number(b.dataset.index);notice='';
 if(action==='raw'){download('Quidence_Game_Theory_Saved_Record.json',raw,'application/json');return;}
 if(['reset','reset-blocked'].includes(action)){document.getElementById('reset-dialog').showModal();return;}
 if(action==='cancel-reset'){document.getElementById('reset-dialog').close();return;}
 if(action==='confirm-reset'){state=E.fresh();blocked=false;raw='';step=0;lab=[0,0];render(true);return;}
 if(blocked)return;
 if(action==='home')state.view='orientation';
 else if(action==='start'){state.view='lesson';lab=[...lesson().start];}
 else if(action==='open'){openLesson(i);return;}
 else if(action==='summary'){if(!E.allDone(state))return;state.view='summary';}
 else if(action==='next'){
  if(E.record(state,currentTask().id).status!=='submitted')return;
  if(state.stage==='predict'){state.stage='learn';step=0;lab=[...lesson().start];}
  else if(state.questionIndex===0)state.questionIndex=1;else showReview();
 }
 else if(action==='step')step=i;
 else if(action==='prev-step')step=Math.max(0,step-1);
 else if(action==='next-step'){if(step<3)step++;else if(state.lessons[state.lessonIndex].seenSteps.length===4){state.stage='check';state.questionIndex=0;}}
 else if(action==='switch-a'||action==='switch-b'){lab[action==='switch-a'?0:1]=1-lab[action==='switch-a'?0:1];E.log(state,'table_explored',{lesson:lesson().id,row:lab[0],col:lab[1]});}
 else if(action==='relearn'){state.stage='learn';step=0;lab=[...lesson().start];}
 else if(action==='revise'){state.stage='check';state.questionIndex=i;}
 else if(action==='continue'){if(E.allDone(state)){state.view='summary';}else{const next=state.lessonIndex<3?state.lessonIndex+1:C.LESSONS.findIndex((_,j)=>!E.lessonDone(state,j));openLesson(next);return;}}
 else if(action==='export-json'){download('Quidence_Game_Theory_Answer_History.json',JSON.stringify(E.exportRecord(state),null,2),'application/json');return;}
 else if(action==='export-md'){download('Quidence_Game_Theory_Learning_Summary.md',markdown(),'text/markdown');return;}
 else if(action==='print'){try{const ok=window.QuidenceReportTools.openPrint(window.QuidenceReportTools.printable(document.title,{markdown:markdown()}));notice=ok?'The report opened in a new tab. Print / save as PDF there.':'Allow pop-ups or download the readable report.';}catch{notice='The report tab could not open. Download the readable report.';}render();return;}
 else return;
 const localAction=state.stage==='learn'&&['step','prev-step','next-step','switch-a','switch-b'].includes(action);
 render(!localAction);
 if(localAction){const target=state.stage==='learn'&&['step','prev-step','next-step'].includes(action)?app.querySelector('h2'):app.querySelector(`[data-action="${action}"]`);if(target){target.tabIndex=-1;target.focus();}}
});
lab=[...lesson().start];render();
})();
